// === Tab: mySketch ===
//Making 2 different particle systems. Each particle system is attracted to a random walker.
//If the system gets to close to its target it "explodes". Sliders are used to change the 
//force strength and max speed value.
var particles = [];
var particles2 = [];

//slider for controling force strength and speed.
var slider, slider2;
//variable for pushing noise controled attractors.
let xoff = 0;

function setup() {

  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100);
  noFill();

  //setting up slider.
  slider = createSlider(0, 1000, 200, 1);
  slider.position(10, 10);

  slider2 = createSlider(0, 100, 5, 0);
  slider2.position(10, 40);


  //filling arrays of particles. Initially creating particles at random position. 
  //initial particle naumber  (i value) affects performance.
  for (i = 0; i <= 30; i++) {
    particles[i] = new Particle(random(width), random(height), 230, 170);
    particles2[i] = new Particle(random(width), random(height), 0, 60);
  }

}

function draw() {
  background(0);

  fill(0, 0, 100);
  noStroke();
  textSize(15);
  text('force: ' + 1/slider.value(), 150, 25);
  text('speed: ' + slider2.value(), 150, 55);


  //Udating all particles.
  for (i = 0; i < particles.length; i++) {
    //First particle system.
    particles[i].attracted(xoff);
    particles[i].update();
    particles[i].checkEdges();
    particles[i].display();
    //Second particle system.
    particles2[i].attracted(xoff + 50000);
    particles2[i].update();
    particles2[i].checkEdges();
    particles2[i].display();

  }
  //Moving forwartd in noise function.
  xoff += 0.05



}

//Press key for an explosion like effect(?).
function keyPressed() {
  for (i = 0; i < particles.length; i += 1) {
    particles[i].hit();
    particles2[i].hit();
  }

}

//Particle calss 
class Particle {

  //arguements : initial x,y position of particles / 2 hues for colorising them.
  constructor(x, y, hue1, hue2) {
    //the system is based on gravitational physics engine.
    this.pos = createVector(x, y); //position
    this.speed = createVector();   //speed
    this.acc = createVector();     //acceleration        
    //an array to store past positions of each particle to create trails.
    this.trail = [];
    //2 colors for lerp color.
    this.color = color(hue1, 100, 80);  //color
    this.colorto = color(hue2, 100, 80);
    //size will change strokeWeight as well as trail length.
    //max value affects performance.
    this.size = random(5, 70); //size
  }

  //update function for moving the particle.Also added acceleration for applying forces.
  update() {
    //this is similar to the Nature of Code phyisics engines by Daniel Shiffman.

    //MOVE
    this.speed.add(this.acc);
    this.pos.add(this.speed);
    //change range to change speed. Randomizing this value prevents perfect alignement of the particles.
    this.speed.limit(random(5, slider2.value()));
    //zero acceleration eache frame.
    this.acc.mult(0);

    //TRAIL
    //copy current position and push it to the trail array.
    let v = this.pos.copy();
    //store the vector to an array for drawing trails.
    this.trail.push(v);
    //limit the size of stored vectors & trail length. This greatly affects performance. Change it accordingly.
    if (this.trail.length > this.size) {
      this.trail.splice(0, 1);
    }
  }

  //fnuction for making sure no particles escape.
  checkEdges() {
    if (this.pos.x > width) {
      this.pos.x = 0;
    } else if (this.pos.x < 0) {
      this.pos.x = width
    } else if (this.pos.y > height) {
      this.pos.y = 0;
    } else if (this.pos.y < 0) {
      this.pos.y = height;
    }
  }

  //this is a function to determine the attraction force of each particle system.
  //Particles can either follow a random walker based on the noise funciton either users mouse.
  //xoff arguement is the index for the noise function used.
  attracted(xoff) {

    //determine x,y position of attractor based on Perlin noise.
    let x = noise(xoff) * width;
    let y = noise(xoff + 10000) * height
    let target = createVector(x, y);

    //Uncomment to follow mouse and comment the previous target declaration.
    //let target = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));

    //force is dependent on the distance of the particle(pos) with the attractor.
    let magn = target.dist(this.pos);

    if (magn > 15) {
      let force = target.sub(this.pos);
      force.limit(magn/slider.value()  );
      this.acc.add(force);
    }

    //if particles go to close to attractor create an explosion effect to prevent perfect alignement. 
    else {
      var force = p5.Vector.random2D();
      force.mult(50);
      this.acc.add(force);
    }

  }


  //Function that creates an explosioN effect on the particles
  hit() {
    let ran = p5.Vector.random2D();
    ran.mult(100);
    this.acc.add(ran);
  }

  //Display particle and trail.
  display() {
    //create a point for each position stored in trail array. This includes current position.
    for (let i = 0; i < this.trail.length; i++) {
      let ps = this.trail[i];
      //using lerp color to create gradient effect towards the end of the trail.
      stroke(lerpColor(this.color, this.colorto, i / this.size));
      //reduce strokeWeight towards the end of the trail.
      strokeWeight(i / 20);
      point(ps.x, ps.y);
    }
  }


  //End of class.
}

